fn term(n: Int) -> Int {
    if n <= 2 {
        return 1
    }
    term(n - 1) + term(n - 2)
}

fn main() {
    print(term(20))
}

fn seq(n: Int) -> Int {
    if n <= 2 {
        1
    } else {
        seq(n - 1) + seq(n - 2)
    }
}

